package utils

import (
	"fmt"
	"os"
	"path/filepath"

	shared "github.com/run-ai/runai/runai-installer/installer/e2e/utils"
)

var (
	TestDomain          = shared.TestDomain
	TestWildcardDomain  = shared.TestWildcardDomain
	TestK8sDistribution string
)

func init() {
	TestDomain = shared.TestDomain
	TestWildcardDomain = shared.TestWildcardDomain
	TestK8sDistribution = os.Getenv("E2E_K8S_DISTRIBUTION")
}

var requiredSecretFiles = []string{
	"runai_jfrog_token",
}

// optionalSecretFiles are copied if present in the source secrets directory.
// TLS material is generated by EnableSelfSignedCA when not provided by the
// workflow, so it is no longer required to ship from outside.
var optionalSecretFiles = []string{
	"tls.crt",
	"tls.key",
	"wildcard.crt",
	"wildcard.key",
	"ca.crt",
}

func CopySecretsFromDir(srcDir, destDir string) error {
	for _, filename := range requiredSecretFiles {
		srcPath := filepath.Join(srcDir, filename)
		destPath := filepath.Join(destDir, filename)

		if err := shared.CopyFile(srcPath, destPath); err != nil {
			return fmt.Errorf("failed to copy %s: %w", filename, err)
		}
	}

	for _, filename := range optionalSecretFiles {
		srcPath := filepath.Join(srcDir, filename)
		destPath := filepath.Join(destDir, filename)

		if err := shared.CopyFile(srcPath, destPath); err == nil {
			fmt.Printf("Copied optional file: %s\n", filename)
		}
	}

	return nil
}
